#!/usr/bin/env bash
# Minimal GIT_ASKPASS helper: answers git's credential prompts from the
# GH_TOKEN already present in the environment. Never echoes the token itself.
case "$1" in
*Username*) printf 'x-access-token\n' ;;
*Password*) printf '%s\n' "$GH_TOKEN" ;;
*) exit 1 ;;
esac

